@Serializable
data class NoteDto(
    @SerialName("note_id") val noteId: String,
    @SerialName("created_at") val createdAt: String? = null,
    val body: String? = null,
)

// The domain model is the contract the rest of the app depends on
data class Note(val id: Long, val createdAt: Instant, val body: String)

fun NoteDto.toDomain(): Note = Note(
    id = noteId.toLong(),
    createdAt = createdAt?.let(Instant::parse) ?: Instant.EPOCH,
    body = body.orEmpty(),
)

sealed interface DomainError {
    data object Network : DomainError
    data object Unauthorized : DomainError
    data object NotFound : DomainError
}

sealed interface Outcome<out T> {
    data class Success<T>(val value: T) : Outcome<T>
    data class Failure(val error: DomainError) : Outcome<Nothing>
}

class NoteRepository(private val api: NoteApi) {
    // Callers only ever see DomainError, never OkHttp or Retrofit types
    suspend fun loadAll(): Outcome<List<Note>> = try {
        Outcome.Success(api.fetchAll().map(NoteDto::toDomain))
    } catch (e: HttpException) {
        when (e.code()) {
            401 -> Outcome.Failure(DomainError.Unauthorized)
            else -> Outcome.Failure(DomainError.Network)
        }
    } catch (e: IOException) {
        Outcome.Failure(DomainError.Network)
    }
}

fun refresh() {
    viewModelScope.launch {
        _state.update { it.copy(isRefreshing = true, error = null) }
        repo.loadAll().fold(
            onSuccess = { notes ->
                _state.update { it.copy(notes = notes, isRefreshing = false) }
            },
            onFailure = { error ->
                _state.update { it.copy(error = error.toMessage(), isRefreshing = false) }
            },
        )
    }
}

@Entity
data class OutboxRow(
    @PrimaryKey val id: String,   // idempotency key, created once at write time
    val seq: Long,                // client order; server applies in this order
    val payload: String,
    val pending: Boolean = true,
    val failed: Boolean = false,
)

class OutboxWorker(
    private val outboxDao: OutboxDao,
    private val api: SyncApi,
) : CoroutineWorker() {

    override suspend fun doWork(): Result {
        for (row in outboxDao.pendingInOrder()) {
            val outcome = runCatching { api.push(row.id, row.seq, row.payload) }
            when {
                outcome.isSuccess -> outboxDao.markSynced(row.id)
                outcome.exceptionOrNull()?.isRetryable() == false -> outboxDao.markFailed(row.id)
                else -> return Result.retry()   // backoff and re-enqueue
            }
        }
        return Result.success()
    }
}

class FeedRepository(
    private val api: FeedApi,
    private val dao: FeedDao,
    private val version: DatasetVersion,
) {
    // The database is the source of truth; reads are always cached-and-correct
    fun observe(): Flow<List<Post>> = dao.observeAll()

    suspend fun refresh() {
        val posts = api.fetchLatest()
        dao.transaction {
            dao.replaceAll(posts)
            version.bump()          // dependent queries re-fetch
        }
    }

    // Invalidation on write: local edit invalidates the read path immediately
    suspend fun save(post: Post) {
        dao.upsert(post)
        version.invalidate(post.id)
    }
}

