    override fun now(): Instant = Instant.ofEpochMilli(System.currentTimeMillis())
}

// iosMain
actual fun platformClock(): Clock = object : Clock {
    override fun now(): Instant = Instant.ofEpochSecond(NSDate().timeIntervalSince1970.toLong())
}

interface RatingStrategy {
    fun order(): Int
    fun apply(candidate: Candidate): Double
}

@Module
@InstallIn(SingletonComponent::class)
object RatingModule {
    @Provides @IntoSet
    fun videoRating(): RatingStrategy = VideoRating()          // order() = 10

    @Provides @IntoSet
    fun engagementRating(): RatingStrategy = EngagementRating() // order() = 20
}

@HiltViewModel
class GradeViewModel @Inject constructor(
    private val strategies: Set<RatingStrategy>,
) : ViewModel() {
    fun score(candidate: Candidate): Double =
        strategies.sortedBy { it.order() }.sumOf { it.apply(candidate) }
}

// Keyed dispatch via @IntoMap + a custom @MapKey
@MapKey
@Retention(AnnotationRetention.BINARY)
annotation class FeatureKey(val name: String)

class FeatureHost @Inject constructor(
    private val handlers: Map<FeatureKey, FeatureHandler>,
) {
    fun dispatch(feature: String) = handlers[FeatureKey(feature)]?.handle() ?: Unit
}
